import{_ as a,o,c as l,a5 as d}from"./chunks/framework.Bt0SrEfo.js";const c=JSON.parse('{"title":"02 AI 编程工具链","description":"","frontmatter":{"title":"02 AI 编程工具链"},"headers":[],"relativePath":"前端/engineering/ai-copilot/02-工具链.md","filePath":"前端/engineering/ai-copilot/02-工具链.md","lastUpdated":1792683759000}'),r={name:"前端/engineering/ai-copilot/02-工具链.md"};function i(e,t,h,n,s,u){return o(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="_02-ai-编程工具链" tabindex="-1">02 AI 编程工具链 <a class="header-anchor" href="#_02-ai-编程工具链" aria-label="Permalink to &quot;02 AI 编程工具链&quot;">​</a></h1><blockquote><p>了解主流 AI 编程工具，明确每种工具的适用场景，避免用错工具。</p></blockquote><nav class="table-of-contents"><ul><li><a href="#_2-1-工具全景图">2.1 工具全景图</a></li><li><a href="#_2-2-各工具详细对比">2.2 各工具详细对比</a><ul><li><a href="#代码补全-copilot-vs-cursor-tab">代码补全：Copilot vs Cursor Tab</a></li><li><a href="#对话式-copilot-chat-vs-cursor-chat">对话式：Copilot Chat vs Cursor Chat</a></li><li><a href="#agent-类-codex-vs-cursor-agent">Agent 类：Codex vs Cursor Agent</a></li></ul></li><li><a href="#_2-3-工具选择决策树">2.3 工具选择决策树</a></li><li><a href="#_2-4-本项目的工具栈">2.4 本项目的工具栈</a></li><li><a href="#_2-5-工具链协同示例">2.5 工具链协同示例</a></li><li><a href="#_2-6-常见误区">2.6 常见误区</a></li><li><a href="#下一步">下一步</a></li><li><a href="#面试常考">面试常考</a><ul><li><a href="#q1-ai-编程工具-3-大类">Q1:AI 编程工具 3 大类?</a></li><li><a href="#q2-codex-工具栈包含什么">Q2:Codex 工具栈包含什么?</a></li><li><a href="#q3-工具选型决策树">Q3:工具选型决策树?</a></li></ul></li></ul></nav><h2 id="_2-1-工具全景图" tabindex="-1">2.1 工具全景图 <a class="header-anchor" href="#_2-1-工具全景图" aria-label="Permalink to &quot;2.1 工具全景图&quot;">​</a></h2><ul><li><p>代码补全类（IDE 内嵌）</p><ul><li>GitHub Copilot — 适合：日常代码补全、简单函数生成</li><li>Cursor (Tab) — 适合：快速代码补全，基于当前文件上下文</li></ul></li><li><p>对话式编程类（IDE 侧边栏）</p><ul><li>GitHub Copilot Chat — 适合：代码解释、单文件重构</li><li>Cursor Chat — 适合：项目级问答、跨文件修改</li><li>JetBrains AI Assistant — 适合：Java/Kotlin 项目</li></ul></li><li><p>Agent 任务执行类（自主执行）</p><ul><li>Codex (codex.ai) — 适合：端到端任务、PR 流程、多文件修改</li><li>Copilot Workspace — 适合：Spec to代码的端到端开发</li><li>Cursor Agent — 适合：复杂任务、可以自主操作文件</li></ul></li><li><p>自动化任务类</p><ul><li>Codex Automate — 适合：定时任务、CI 监控、发布检查</li><li>GitHub Actions + AI — 适合：PR 自动审查、定时检查</li><li>CI Pipeline + LLM — 适合：构建失败自动分析</li></ul></li></ul><h2 id="_2-2-各工具详细对比" tabindex="-1">2.2 各工具详细对比 <a class="header-anchor" href="#_2-2-各工具详细对比" aria-label="Permalink to &quot;2.2 各工具详细对比&quot;">​</a></h2><h3 id="代码补全-copilot-vs-cursor-tab" tabindex="-1">代码补全：Copilot vs Cursor Tab <a class="header-anchor" href="#代码补全-copilot-vs-cursor-tab" aria-label="Permalink to &quot;代码补全：Copilot vs Cursor Tab&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>GitHub Copilot</th><th>Cursor Tab</th></tr></thead><tbody><tr><td>补全速度</td><td>快</td><td>极快</td></tr><tr><td>上下文感知</td><td>好</td><td>更好（基于项目）</td></tr><tr><td>长代码生成</td><td>一般</td><td>强</td></tr><tr><td>价格</td><td>10美元/月</td><td>20美元/月（含 Pro 功能）</td></tr><tr><td>适合场景</td><td>日常补全</td><td>需要强上下文的长代码</td></tr></tbody></table><h3 id="对话式-copilot-chat-vs-cursor-chat" tabindex="-1">对话式：Copilot Chat vs Cursor Chat <a class="header-anchor" href="#对话式-copilot-chat-vs-cursor-chat" aria-label="Permalink to &quot;对话式：Copilot Chat vs Cursor Chat&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Copilot Chat</th><th>Cursor Chat</th></tr></thead><tbody><tr><td>可用范围</td><td>VS Code 内</td><td>全项目</td></tr><tr><td>文件修改</td><td>直接改文件</td><td>直接改文件</td></tr><tr><td>知识库</td><td>无</td><td>可上传文档</td></tr><tr><td>价格</td><td>10美元/月</td><td>20美元/月</td></tr></tbody></table><h3 id="agent-类-codex-vs-cursor-agent" tabindex="-1">Agent 类：Codex vs Cursor Agent <a class="header-anchor" href="#agent-类-codex-vs-cursor-agent" aria-label="Permalink to &quot;Agent 类：Codex vs Cursor Agent&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Codex</th><th>Cursor Agent</th></tr></thead><tbody><tr><td>执行模式</td><td>对话 + 任务</td><td>自主文件操作</td></tr><tr><td>多文件修改</td><td>强</td><td>强</td></tr><tr><td>Skill 系统</td><td>有（/automate, /autopilot）</td><td>无</td></tr><tr><td>多 Agent 协作</td><td>支持</td><td>不支持</td></tr><tr><td>价格</td><td>20美元/月</td><td>20美元/月</td></tr><tr><td>适合任务</td><td>端到端任务流（PR 流程、自动化）</td><td>单次复杂修改（重构、多文件改动）</td></tr></tbody></table><h2 id="_2-3-工具选择决策树" tabindex="-1">2.3 工具选择决策树 <a class="header-anchor" href="#_2-3-工具选择决策树" aria-label="Permalink to &quot;2.3 工具选择决策树&quot;">​</a></h2><ul><li>任务类型是什么？ <ul><li>单文件/单函数修改：Copilot Chat 或 Cursor Chat 即可</li><li>端到端任务（多文件 + 测试 + 验证）：Codex（开 Thread，让 AI 自主执行）</li><li>PR 自动审查 / 定时检查：Codex Automate 或 /autopilot</li><li>日常代码补全：Copilot 或 Cursor Tab</li><li>需要参考项目文档/知识库：Cursor Chat（可上传知识库）</li></ul></li></ul><h2 id="_2-4-本项目的工具栈" tabindex="-1">2.4 本项目的工具栈 <a class="header-anchor" href="#_2-4-本项目的工具栈" aria-label="Permalink to &quot;2.4 本项目的工具栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>场景</th></tr></thead><tbody><tr><td>Codex</td><td>主要 AI 协作工具</td><td>代码生成、PR 流程、自动化</td></tr><tr><td>Copilot</td><td>IDE 内补全</td><td>日常代码片段补全</td></tr><tr><td>Codex /autopilot</td><td>PR 自动审查</td><td>保持 PR 可合并状态</td></tr><tr><td>Codex /automate</td><td>定时任务</td><td>CI 监控、依赖检查</td></tr><tr><td>Codex Canvas</td><td>可视化分析</td><td>数据图表、性能分析报告</td></tr></tbody></table><h2 id="_2-5-工具链协同示例" tabindex="-1">2.5 工具链协同示例 <a class="header-anchor" href="#_2-5-工具链协同示例" aria-label="Permalink to &quot;2.5 工具链协同示例&quot;">​</a></h2><ul><li>日常开发（Copilot）：IDE 内实时补全</li><li>单文件修改（Copilot Chat）：解释、重构单文件</li><li>端到端任务（Codex）：新功能开发，AI 生成 to跑测试 to报告</li><li>PR 流程（Codex /autopilot）：自动审查 + 解决冲突</li><li>定时任务（Codex /automate）：自动化 CI 监控</li></ul><h2 id="_2-6-常见误区" tabindex="-1">2.6 常见误区 <a class="header-anchor" href="#_2-6-常见误区" aria-label="Permalink to &quot;2.6 常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确做法</th></tr></thead><tbody><tr><td>所有任务都用 Copilot Chat</td><td>Copilot Chat 适合单文件，复杂任务用 Codex</td></tr><tr><td>Codex 和 Copilot 功能重复</td><td>两者互补：Copilot 做补全，Codex 做任务</td></tr><tr><td>AI 生成的代码不用测</td><td>AI 幻觉率存在，所有 AI 生成代码必须跑测试验证</td></tr><tr><td>直接让 AI 写整个功能</td><td>先拆解任务，AI 每次只做一个闭环子任务</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./03-codex-基础">03-codex-基础</a> — 用 Codex 做日常代码场景</li></ul><h2 id="面试常考" tabindex="-1">面试常考 <a class="header-anchor" href="#面试常考" aria-label="Permalink to &quot;面试常考&quot;">​</a></h2><h3 id="q1-ai-编程工具-3-大类" tabindex="-1">Q1:AI 编程工具 3 大类? <a class="header-anchor" href="#q1-ai-编程工具-3-大类" aria-label="Permalink to &quot;Q1:AI 编程工具 3 大类?&quot;">​</a></h3><p><strong>答</strong>:</p><ul><li><strong>补全型</strong>:Copilot、Codeium(IDE 插件,行内补全)</li><li><strong>任务型</strong>:Codex、Cursor Composer(端到端任务)</li><li><strong>专项型</strong>:v0(UI 生成)、Bolt(全栈 demo)</li><li>选:日常编码补全型;复杂任务用任务型</li></ul><h3 id="q2-codex-工具栈包含什么" tabindex="-1">Q2:Codex 工具栈包含什么? <a class="header-anchor" href="#q2-codex-工具栈包含什么" aria-label="Permalink to &quot;Q2:Codex 工具栈包含什么?&quot;">​</a></h3><p><strong>答</strong>:</p><ul><li><strong>MCP</strong>:Model Context Protocol(连接外部工具)</li><li><strong>Skill</strong>:可复用的工作流定义</li><li><strong>AGENTS.md</strong>:项目级规则文件</li><li><strong>Automate</strong>:定时任务(heartbeat / cron)</li><li><strong>Sub-agent</strong>:多 agent 协作</li></ul><h3 id="q3-工具选型决策树" tabindex="-1">Q3:工具选型决策树? <a class="header-anchor" href="#q3-工具选型决策树" aria-label="Permalink to &quot;Q3:工具选型决策树?&quot;">​</a></h3><p><strong>答</strong>:</p><ul><li>改 1-2 个文件:用补全型</li><li>跨多文件改动:用 Agent(Codex)</li><li>探索新想法/UI:用 v0 / Bolt</li><li>团队协作:用 Codex + AGENTS.md 统一规范</li></ul>',32)])])}const b=a(r,[["render",i]]);export{c as __pageData,b as default};
